import type { Pool } from 'pg';

/**
 * The two tables `createPostgresShell` needs, plus the row-level-security
 * policies that make `tenant_id` an actually-enforced boundary rather than
 * a column every query merely happens to remember to filter by.
 *
 * `xhis_shell_commits`'s `PRIMARY KEY (tenant_id, version)` is not just an
 * index: it is the entire optimistic-concurrency mechanism. `version` is
 * never generated by the database (no `SERIAL`/`IDENTITY`) — the caller
 * computes "the version after the one it most recently read" and tries to
 * insert exactly that row; if a second writer already inserted that same
 * `(tenant_id, version)` pair first, this constraint makes the loser's
 * `INSERT` fail with a `23505` unique-violation, atomically, at the one
 * place that can actually see every concurrent writer — see
 * `postgresShell.ts` and `conflictError.ts` for how that failure gets
 * translated into something `act()`'s caller can react to.
 *
 * `xhis_shell_audit` has no such constraint: an audit record is written
 * for every Act outcome, including rejections, by definition never
 * conflicts with another audit record, and multiple writers appending
 * concurrently is exactly what's expected — only `seq` (a plain
 * `BIGSERIAL`, no tenant-scoped meaning beyond insertion order) need be
 * unique.
 *
 * RLS: enabling it is *not* enough on its own — by default Postgres lets
 * a table's owner (and any superuser) bypass RLS entirely, which is
 * exactly the role most connection strings end up using in a simple
 * setup. `FORCE ROW LEVEL SECURITY` closes that specific hole so the
 * owner is bound by these policies too. The policies themselves compare
 * against `current_setting('app.tenant_id', true)` — the `true` makes it
 * return `NULL` instead of erroring when unset, and `tenant_id = NULL` is
 * never true, so a query that forgot to set it is rejected outright
 * (fails closed) rather than silently seeing every tenant's rows.
 * `postgresShell.ts`'s `withTenantConnection` is what actually sets that
 * per-transaction, via `set_config(..., true)` (not a literal `SET LOCAL
 * app.tenant_id = $1` — Postgres's `SET` statement does not accept a
 * bound parameter there; `set_config` is the parameterizable equivalent)
 * — see that file's own doc comment for why this has to be scoped to one
 * transaction on one checked-out client, never the whole pool.
 *
 * Every statement here is idempotent (`IF NOT EXISTS`, or an explicit
 * `DROP POLICY IF EXISTS` first for the two statements that have no
 * `IF NOT EXISTS` form in Postgres), so `ensureSchema` is safe to call on
 * every process startup, not just once.
 */
export const POSTGRES_SHELL_SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS xhis_shell_commits (
  tenant_id TEXT NOT NULL,
  version BIGINT NOT NULL,
  context JSONB NOT NULL,
  effects JSONB NOT NULL,
  committed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, version)
);

CREATE TABLE IF NOT EXISTS xhis_shell_audit (
  tenant_id TEXT NOT NULL,
  seq BIGSERIAL PRIMARY KEY,
  record JSONB NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS xhis_shell_audit_tenant_seq_idx ON xhis_shell_audit (tenant_id, seq);

ALTER TABLE xhis_shell_commits ENABLE ROW LEVEL SECURITY;
ALTER TABLE xhis_shell_commits FORCE ROW LEVEL SECURITY;
ALTER TABLE xhis_shell_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE xhis_shell_audit FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS xhis_shell_commits_tenant_isolation ON xhis_shell_commits;
CREATE POLICY xhis_shell_commits_tenant_isolation ON xhis_shell_commits
  USING (tenant_id = current_setting('app.tenant_id', true));

DROP POLICY IF EXISTS xhis_shell_audit_tenant_isolation ON xhis_shell_audit;
CREATE POLICY xhis_shell_audit_tenant_isolation ON xhis_shell_audit
  USING (tenant_id = current_setting('app.tenant_id', true));
`;

/** Creates (or, on a later call, confirms) the schema `createPostgresShell`
 * needs. Call once per process startup, before constructing any shell
 * against this `pool` — not automatically inside `createPostgresShell`
 * itself, so that who owns schema migrations (this call, versus a
 * separately-run migration tool) is always the caller's explicit choice,
 * never implicit in constructing a shell. */
export async function ensureSchema(pool: Pool): Promise<void> {
  await pool.query(POSTGRES_SHELL_SCHEMA_SQL);
}
